/**
 * Private paging helpers shared by the repositories in this directory.
 *
 * Not part of the public data-access surface — repositories re-export nothing
 * from here. Keyset (cursor) pagination is expressed as a row-value comparison
 * so a page boundary is stable even when two rows share a `created_at`.
 */
import { sql } from "drizzle-orm";
import { decodeCursor, encodeCursor } from "./base-repository";
import { makePage } from "@/types/common";
import type { Page } from "@/types/common";
import type { SQL } from "drizzle-orm";
import type { SQLiteColumn } from "drizzle-orm/sqlite-core";

export interface KeysetSort {
  readonly sortColumn: SQLiteColumn;
  readonly idColumn: SQLiteColumn;
}

/**
 * Predicate that resumes a descending listing after `cursor`. Returns
 * `undefined` for a first page or an unparseable cursor — a bad cursor
 * degrades to "start from the top", never to an error page.
 */
export function keysetPredicate(
  sort: KeysetSort,
  cursor: string | null | undefined,
): SQL | undefined {
  if (!cursor) return undefined;
  const decoded = decodeCursor(cursor);
  if (!decoded) return undefined;

  return sql`(${sort.sortColumn}, ${sort.idColumn}) < (${decoded.sortValue}, ${decoded.id})`;
}

/** SQLite tolerates a `LIMIT` of `n + 1`; that extra row is the has-more probe. */
export function probeLimit(limit: number): number {
  return Math.max(1, Math.min(limit, 100)) + 1;
}

/**
 * Turns an over-fetched row array into a `Page`, dropping the probe row and
 * deriving the next cursor from the last row that survived.
 */
export function toPage<TRow, TOut>(
  rows: readonly TRow[],
  limit: number,
  total: number,
  map: (row: TRow) => TOut,
  cursorOf: (row: TRow) => { id: string; sortValue: string },
): Page<TOut> {
  const capped = Math.max(1, Math.min(limit, 100));
  const hasMore = rows.length > capped;
  const visible = hasMore ? rows.slice(0, capped) : rows;
  const last = visible.at(-1);

  const nextCursor =
    hasMore && last
      ? encodeCursor(cursorOf(last).id, cursorOf(last).sortValue)
      : null;

  return makePage(visible.map(map), nextCursor, total);
}

/** Drops the `undefined` slots so `and(...)` never sees a hole. */
export function compact(
  ...predicates: readonly (SQL | undefined)[]
): readonly SQL[] {
  return predicates.filter((value): value is SQL => value !== undefined);
}
/**
 * Shared query helpers: cursor encoding, `orgId` predicate construction and the archived-row predicate every other repository composes.
 *
 * Must call (do not reimplement): shouldFilterArchived
 */
import { eq, isNull } from "drizzle-orm";
import { shouldFilterArchived } from "@/lib/soft-delete";
import type { ArchiveScope, OrgId } from "@/types/common";
import type { SQL } from "drizzle-orm";
import type { SQLiteColumn } from "drizzle-orm/sqlite-core";

const CURSOR_SEPARATOR = "|";

/**
 * Cursors are opaque to callers: base64url of `<sortValue>|<id>`. Encoding the
 * sort value alongside the id is what lets `listX` resume from a stable point
 * even when two rows share a timestamp.
 */
export function encodeCursor(id: string, sortValue: string): string {
  return Buffer.from(`${sortValue}${CURSOR_SEPARATOR}${id}`, "utf8").toString(
    "base64url",
  );
}

export function decodeCursor(
  cursor: string,
): { id: string; sortValue: string } | null {
  let decoded: string;
  try {
    decoded = Buffer.from(cursor, "base64url").toString("utf8");
  } catch {
    return null;
  }

  const separatorAt = decoded.lastIndexOf(CURSOR_SEPARATOR);
  if (separatorAt <= 0 || separatorAt === decoded.length - 1) return null;

  return {
    sortValue: decoded.slice(0, separatorAt),
    id: decoded.slice(separatorAt + 1),
  };
}

/**
 * The tenant predicate. Every repository read and write composes this — a
 * query that does not mention `org_id` is a cross-tenant leak waiting to
 * happen, so this is the only sanctioned way to express it.
 */
export function orgPredicate(column: SQLiteColumn, orgId: OrgId): SQL {
  return eq(column, orgId);
}

/**
 * The soft-delete predicate, or `undefined` when the caller explicitly asked
 * for archived rows. The `includeArchived` decision itself lives in
 * `shouldFilterArchived()` so it cannot drift per repository.
 */
export function livePredicate(
  column: SQLiteColumn,
  scope: ArchiveScope,
): SQL | undefined {
  return shouldFilterArchived(scope) ? isNull(column) : undefined;
}
/**
 * Turns a repository `Page` into what the pagination UI needs. Repositories
 * return cursor pages; the UI wants page counts and a "there is more" cursor,
 * and this module is the translation between the two.
 */
import { DEFAULT_PAGE_SIZE, MAX_PAGE_SIZE } from "@/config/constants";
import type { Page } from "@/types/common";
import { makePage } from "@/types/common";

/** Number of pages a total spans; always at least 1 so the UI can render "1 of 1". */
export function pageCount(total: number, perPage: number): number {
  const size = clampPageSize(perPage);
  if (total <= 0) return 1;
  return Math.ceil(total / size);
}

/** Clamps a caller-supplied page size into the range the schemas allow. */
export function clampPageSize(perPage: number): number {
  if (!Number.isFinite(perPage) || perPage <= 0) return DEFAULT_PAGE_SIZE;
  return Math.min(Math.floor(perPage), MAX_PAGE_SIZE);
}

export function emptyPage<T>(): Page<T> {
  return makePage<T>([], null, 0);
}

/**
 * Trims an over-fetched row set to one page. Repositories query `limit + 1`
 * rows; if the extra row came back there is a next page, and its cursor is
 * the last kept row's cursor.
 */
export function sliceToPage<T>(
  items: readonly T[],
  limit: number,
  total: number,
  cursorOf: (item: T) => string,
): Page<T> {
  const size = clampPageSize(limit);
  const hasMore = items.length > size;
  const kept = hasMore ? items.slice(0, size) : items.slice();
  const last = kept[kept.length - 1];
  return makePage(kept, hasMore && last !== undefined ? cursorOf(last) : null, total);
}
/**
 * Resolves the request's `Actor` for a given org slug, or throws
 * `unauthorized` / `forbidden`. Every Server Action starts here.
 *
 * The `Actor` is the only thing `can()` and `assertOrgScope()` accept, so
 * this module is the seam between "there is an HTTP request with a cookie"
 * and the rest of the app, which knows nothing about requests.
 */
import { getSessionPrincipal } from "@/lib/session";
import { assertOrgScope } from "@/lib/tenant";
import { findOrgById } from "@/server/repositories/organization-repository";
import { resolveActorForOrg } from "@/server/services/session-service";
import type { OrgId } from "@/types/common";
import type { Actor } from "@/types/member";

/** Thrown when there is no usable session; mapped to a 401 by `toAppError`. */
export class UnauthorizedError extends Error {
  readonly code = "unauthorized" as const;

  constructor(message = "Sign in to continue.") {
    super(message);
    this.name = "UnauthorizedError";
  }
}

/** Thrown when the session is valid but has no membership in the target org. */
export class NoMembershipError extends Error {
  readonly code = "forbidden" as const;

  constructor(readonly orgSlug: string) {
    super(`You are not a member of "${orgSlug}".`);
    this.name = "NoMembershipError";
  }
}

/** The `Actor` for `orgSlug`, or a throw. Use this in Server Actions. */
export async function getActor(orgSlug: string): Promise<Actor> {
  const principal = await getSessionPrincipal();
  if (principal === null) throw new UnauthorizedError();

  const actor = await resolveActorForOrg(principal, orgSlug);
  if (actor === null) throw new NoMembershipError(orgSlug);

  return actor;
}

/** Non-throwing variant, for layouts that render a signed-out state. */
export async function tryGetActor(orgSlug: string): Promise<Actor | null> {
  try {
    return await getActor(orgSlug);
  } catch (error) {
    if (error instanceof UnauthorizedError || error instanceof NoMembershipError) {
      return null;
    }
    throw error;
  }
}

/**
 * The `Actor` for an org already identified by id — used by Route Handlers
 * that receive an `orgId` in the payload rather than a slug in the path. The
 * session's active org must match, which `assertOrgScope()` enforces.
 *
 * `resolveActorForOrg` keys off the org *slug*, so the id is translated here
 * with a single repository lookup rather than by widening that signature —
 * the slug is the only handle the session layer knows.
 */
export async function requireActorFor(orgId: OrgId): Promise<Actor> {
  const principal = await getSessionPrincipal();
  if (principal === null) throw new UnauthorizedError();
  if (principal.activeOrgId === null) throw new NoMembershipError(orgId);

  const org = await findOrgById(orgId);
  if (org === null) throw new NoMembershipError(orgId);

  const actor = await resolveActorForOrg(principal, org.slug);
  if (actor === null) throw new NoMembershipError(org.slug);

  assertOrgScope(actor, orgId);
  return actor;
}
/**
 * RFC-4180 CSV writer used by both export routes (issues and the audit log).
 *
 * The rules that matter: fields containing a comma, a double quote or a line
 * break are wrapped in double quotes and every embedded quote is doubled;
 * rows are separated by CRLF; column order comes from the caller, never from
 * object key order.
 */

const NEEDS_QUOTING = /[",\r\n]/;

export function escapeCsvValue(value: string | number | boolean | null): string {
  if (value === null) return "";
  const text = String(value);
  if (!NEEDS_QUOTING.test(text)) return text;
  return `"${text.replace(/"/g, '""')}"`;
}

/**
 * Serialises `rows` using `columns` as both the header line and the field
 * order. A column missing from a row is written as an empty field.
 */
export function toCsv(
  rows: readonly Readonly<Record<string, string | number | boolean | null>>[],
  columns: readonly string[],
): string {
  const lines: string[] = [columns.map(escapeCsvValue).join(",")];

  for (const row of rows) {
    lines.push(
      columns
        .map((column) => escapeCsvValue(row[column] ?? null))
        .join(","),
    );
  }

  return lines.join("\r\n");
}

/** The headers an export Route Handler returns alongside the CSV body. */
export function csvResponseHeaders(
  filename: string,
): Readonly<Record<string, string>> {
  const safe = filename.replace(/[^A-Za-z0-9._-]/g, "-");
  return {
    "Content-Type": "text/csv; charset=utf-8",
    "Content-Disposition": `attachment; filename="${safe}"`,
    "Cache-Control": "no-store",
  };
}
